insert into public.together_worlds(
  id,name,slug,description,hero_asset_key,theme,metadata,published,access_type,entitlement_key,
  timezone,sort_order,featured,visual_context,world_role,social_rhythm,dominant_dayparts,
  relationship_themes,activity_families,mobility_style,weather_profile,default_arrival_location_id
) values(
  '10000000-0000-4000-8000-000000000011','NorthVale','northvale','A contemporary Colorado ski town where year-round locals, seasonal workers, mountain professionals, artists, athletes, and travelers build intimate lives beneath a resort economy shaped by weather, risk, and the question of who gets to stay.','northvale-hero',
  '{"accent":["snow blue","pine green","firelight amber"]}'::jsonb,
  $northvale_world_meta${"releaseWave":10,"releaseStatus":"playable","contentStatus":"complete_world_v1","locationCount":51,"districtCount":6,"publicPlaceCount":45,"residentCompanionCount":45,"residentGenderRatio":{"women":30,"men":15},"residentScheduleStatus":"authored_weekly_v2","socialGraphStatus":"authored_v1","locationImageSlotCount":51,"recurringEventCount":6,"storyArcCount":7,"genreTags":["modern mountain romance","ski town","found family","workplace","outdoor adventure","community drama"],"nativeDateSeeds":["First Tracks Before Sunrise","A Storm-Hold Drink","Lantern Skate at Pine Lake","A Mud-Season Road Trip","Hot Springs After Patrol","Closing the Mountain Together"],"storySeeds":["The White Sunday Log","The Silver Basin Line","One More Winter","The Last Reel","Second Descent","The Broken Cable","The Cabin at Mile Nine"],"populationArchetypes":["ski patroller","lift operator","seasonal bartender","avalanche forecaster","hotel manager","ski instructor","guide","chef","clinic physician","artist","mechanic","Nordic coach","town planner","wildlife biologist"],"featuredCharacterIds":[1,8,15,22,23,32,39,40],"early_access":true,"locationCatalogStatus":"ready","residentRosterStatus":"ready","photoStatus":"hero_ready","locationPhotoStatus":"ready","mappedLocationPhotoCount":51,"residentPortraitStatus":"primary_portraits_ready","mappedResidentPortraitCount":45,"tagline":"Everyone comes for the snow. The reason they stay is usually a person.","relationshipFantasy":"Fall for someone whose temporary winter life may be turning into a permanent home.","centralQuestion":"What makes a place home when almost everyone arrived planning to leave?","originYear":1884,"approximatePopulation":11800,"peakWinterPopulation":34000,"townElevationFeet":8350,"summitElevationFeet":12440,"canonicalLore":{"before_the_town":"The North Fork valley lies within the ancestral homelands of the Nuche, or Ute peoples. Long before mining claims, ski maps, and real-estate brochures, the valley was part of a much larger living landscape of seasonal movement, hunting, trade, ceremony, and family memory. Modern NorthVale acknowledges that history imperfectly: the town funds cultural consultation and watershed work, while residents still debate whether acknowledgement has translated into meaningful authority.","mining_foundation":"North Vale began in 1884 as a silver camp where Alder Creek meets the North Fork. The richest claims lasted less than twenty years, but a rail spur, Miners Hall, boarding houses, repair shops, and a stubborn year-round population kept the settlement alive after the boom. The town's oldest families are not cattle barons or aristocrats; they are descendants of cooks, laborers, shopkeepers, railway workers, teachers, miners, and migrants who learned how to survive an expensive, isolated valley together.","white_sunday":"On February 18, 1912, a massive avalanche crossed the old mine road during a church and market day remembered as White Sunday. Forty-one people died and dozens more were rescued by neighbors using shovels, timber, and improvised sleds. The disaster created NorthVale's culture of mountain responsibility: local status means little when weather turns, safety knowledge is shared, and anyone who ignores a closure endangers the people who must come after them.","ski_town":"In 1947, returning mountain soldiers, former miners, and local teachers built a rope tow on the north-facing slope above town. What began as a community winter project became NorthVale Mountain. The resort grew in stages rather than appearing fully formed, and generations of residents worked lifts, patrolled runs, taught lessons, cooked, tuned equipment, cleaned rooms, and opened businesses around it. The mountain is both the town's economic engine and the source of its most persistent arguments.","vale_accord":"The Vale Accord of 1978 allowed a major resort expansion only after the operator committed to public trail access, watershed monitoring, search-and-rescue funding, community passes, and a permanent contribution to worker housing. Its fifty-year renewal window opened in 2026. Almost everyone agrees the Accord matters; almost nobody agrees what a modern version should require or how much the town can demand without jeopardizing the jobs that keep it alive.","modern_day":"NorthVale is a real town beneath the destination image: public schools, a clinic, apartments above old storefronts, service alleys behind polished lodges, exhausted shift workers, competitive athletes, families, artists, and people who arrived for one winter fifteen years ago. Peak season is crowded, intimate, and slightly reckless. Mud season strips the performance away. Summer replaces skis with bikes, horses, climbing, lake days, trail work, weddings, and construction. Autumn is brief, golden, and full of decisions.","present_season":"The current winter begins after a warm, dry autumn and an abrupt series of early storms. NorthVale Mountain proposes replacing its aging Sunrise Gondola and opening controlled access into Silver Basin. Juniper House, the largest seasonal-worker residence, may be sold after the season. New snowpack data raises safety questions that are real but not simple. A missing page has also resurfaced from the White Sunday patrol record. These threads overlap, but there is no single villain—only people with competing responsibilities, incomplete information, and private reasons to care."}}$northvale_world_meta$::jsonb,true,'subscription','worlds.standard','America/Denver',100,true,
  $northvale_visual${"setting":"A contemporary American alpine town in a steep Colorado valley beneath a major ski mountain, with an older mining-era center, a polished but human-scale resort base, worker neighborhoods, frozen lake, and remote high country.","geography":["steep snow-covered valley","north-facing ski mountain","pine and aspen forest","frozen alpine lake","high basin and avalanche paths","two-lane mountain highway"],"architecture":["restored brick and timber mining-town storefronts","stone-and-cedar lodges","practical employee housing","modern mountain operations buildings","lakeside cabins","weathered backcountry structures"],"climate":"Long snowy winters, sudden high-country storms, bright bluebird cold, muddy spring shoulders, dry active summers, and brief golden aspen autumns.","visual_style":["photorealistic contemporary alpine romance","warm amber interiors against blue snow","lived-in service spaces beside destination polish","realistic winter clothing and equipment","social warmth without holiday-card artificiality"],"palette":["snow blue","pine green","charcoal","weathered cedar","rust","alpine red","firelight amber"],"recurring_elements":["gondola cabins","steam from breath and hot springs","ski racks","employee shuttles","snowbanks","fire pits","trail maps","wet boots near doors","storm boards","warm windows after dark"],"signage_style":["restrained sans-serif resort wayfinding","hand-painted historic storefront signs","enamel trail markers","simple municipal plaques"],"avoid":["readable logos","real brand names","European fairytale village exaggeration","ultra-luxury mansion focus","cowboy ranch iconography","permanent Christmas decor","empty generic stock-resort scenes","purple cyberpunk lighting"]}$northvale_visual$::jsonb,'home','balanced',
  array['early_morning','late_afternoon','evening','late_night']::text[],array['temporary lives becoming permanent','competence and trust','staying versus leaving','class without caricature','risk and responsibility','chosen family','public confidence and private uncertainty','weather-forced intimacy']::text[],array['skiing and snowboarding','apres and live music','mountain operations','lake and sauna rituals','historic town life','food and hospitality','backcountry guiding','summer trail culture','community events']::text[],
  'mixed',$northvale_weather${"climate":"high alpine continental","states":["light_snow","heavy_snow","bluebird_cold","wind_hold","overcast","spring_melt","summer_clear"],"outdoor_bias":0.62}$northvale_weather$::jsonb,null
)
